    ts: "import { Component } from '@angular/core';\nimport { MatExpansionModule } from '@angular/material/expansion';\n\n/**\n * Accordion\n * Accordion Size=Default : conteneur Border/Strong Radius/L (classe gui-accordion), panneaux séparés\n * par Border/Subtle, en-tête 48 px en Body 1 avec chevron 24, survol Action/Neutral/Subtle, contenu\n * Body 2. Un seul panneau ouvert à la fois (comportement par défaut de mat-accordion).\n */\n@Component({\n  selector: 'ex-accordeon-simple',\n  imports: [MatExpansionModule],\n  templateUrl: './accordeon-simple.html',\n  styleUrl: './accordeon-simple.css',\n})\nexport class AccordeonSimple {}\n",
    html: "<mat-accordion class=\"gui-accordion\">\n  <mat-expansion-panel expanded>\n    <mat-expansion-panel-header>\n      <mat-panel-title>Entrée de ligne</mat-panel-title>\n    </mat-expansion-panel-header>\n    <p>Dérouleuses, soudeuse et accumulateur d'entrée. Deux bobines engagées, accumulateur rempli à 80 %.</p>\n  </mat-expansion-panel>\n  <mat-expansion-panel>\n    <mat-expansion-panel-header>\n      <mat-panel-title>Section centrale</mat-panel-title>\n    </mat-expansion-panel-header>\n    <p>Four de recuit, bain de zinc et refroidissement.</p>\n  </mat-expansion-panel>\n  <mat-expansion-panel>\n    <mat-expansion-panel-header>\n      <mat-panel-title>Sortie de ligne</mat-panel-title>\n    </mat-expansion-panel-header>\n    <p>Accumulateur de sortie, cisaille et enrouleuses.</p>\n  </mat-expansion-panel>\n</mat-accordion>\n",
